-- ============================================
-- 001: unidades ejecutoras, DNI y bloqueo por intentos fallidos en USUARIOS,
-- rol asesor_ejecutora (mismo cambio que tables/00_*, 01_usuarios y seeds/)
-- ============================================
CREATE TABLE IF NOT EXISTS "UNIDADES_EJECUTORAS" (
    "ID_UNIDAD_EJECUTORA" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_UNIDADES_EJECUTORAS" PRIMARY KEY,
    "CODIGO" VARCHAR(10) NULL,
    "NOMBRE" VARCHAR(200) NOT NULL CONSTRAINT "UQ_UNIDADES_EJECUTORAS_NOMBRE" UNIQUE,
    "SIGLA" VARCHAR(30) NULL,
    "ES_SEDE_CENTRAL" BOOLEAN NOT NULL DEFAULT FALSE,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE
);

ALTER TABLE "USUARIOS" ADD COLUMN IF NOT EXISTS "DNI" CHAR(8) NULL;
ALTER TABLE "USUARIOS" ADD COLUMN IF NOT EXISTS "ID_UNIDAD_EJECUTORA" INT NULL
    CONSTRAINT "FK_USUARIOS_UNIDAD_EJECUTORA" REFERENCES "UNIDADES_EJECUTORAS" ("ID_UNIDAD_EJECUTORA");
ALTER TABLE "USUARIOS" ADD COLUMN IF NOT EXISTS "INTENTOS_FALLIDOS" INT NOT NULL DEFAULT 0;
ALTER TABLE "USUARIOS" ADD COLUMN IF NOT EXISTS "BLOQUEADO_HASTA" TIMESTAMPTZ NULL;
CREATE UNIQUE INDEX IF NOT EXISTS "UX_USUARIOS_DNI" ON "USUARIOS" ("DNI") WHERE "DNI" IS NOT NULL;

INSERT INTO "UNIDADES_EJECUTORAS" ("NOMBRE", "SIGLA", "ES_SEDE_CENTRAL")
SELECT 'Sede Central', 'SEDE', TRUE
WHERE NOT EXISTS (SELECT 1 FROM "UNIDADES_EJECUTORAS" WHERE "ES_SEDE_CENTRAL" = TRUE);

INSERT INTO "ROLES" ("NOMBRE_ROL", "DESCRIPCION", "NIVEL_ACCESO", "ES_SISTEMA")
VALUES ('asesor_ejecutora', 'Asesor legal de unidad ejecutora: consulta los informes publicados', 1, FALSE)
ON CONFLICT ("NOMBRE_ROL") DO NOTHING;
